using System;using System.IO;using System.Reflection;using System.Threading;using System.Windows.Forms;using SlopProX;
internal static class TransportIntegrationTests{
 static AppSettings Settings(){var s=new AppSettings();s.Integration.QuickStart=false;return s;}static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;static void Wait(int ms){DateTime end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(5);}}
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Form form=null;ArrangementEngine engine=null;try{Type type=typeof(AppSettings).Assembly.GetType("SlopProX.MainForm");LocaleCatalog locale=LocaleCatalog.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"locales","en-US.json"),"en-US");form=(Form)Activator.CreateInstance(type,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Settings(),locale,false,null},null);form.Show();Wait(150);engine=(ArrangementEngine)type.GetField("_engine",flags).GetValue(form);MethodInfo key=type.GetMethod("SendTestShortcut",flags);object timeline=type.GetField("_timeline",flags).GetValue(form);Control canvas=(Control)timeline.GetType().GetField("_canvas",flags).GetValue(timeline);canvas.Focus();key.Invoke(form,new object[]{Keys.Space});Wait(100);if(!engine.Playing)throw new Exception("Play failed");key.Invoke(form,new object[]{Keys.Decimal});double paused=engine.PositionBeat;Wait(120);if(engine.Playing||Math.Abs(engine.PositionBeat-paused)>0.001)throw new Exception("Pause did not hold position");key.Invoke(form,new object[]{Keys.Decimal});Wait(100);if(!engine.Playing||engine.PositionBeat<=paused)throw new Exception("Resume failed");key.Invoke(form,new object[]{Keys.Enter});if(engine.Playing||Math.Abs(engine.PositionBeat)>0.0001)throw new Exception("Return-to-start failed");MethodInfo click=canvas.GetType().GetMethod("OnMouseDown",flags);int header=(int)canvas.GetType().GetField("HeaderWidth").GetValue(canvas);click.Invoke(canvas,new object[]{new MouseEventArgs(MouseButtons.Left,1,DisplayScale.Pixels(canvas,header+80),DisplayScale.Pixels(canvas,20),0)});if(Math.Abs(engine.PositionBeat-10)>0.01)throw new Exception("Ruler seek failed: "+engine.PositionBeat);File.WriteAllText(args[0],"PASS actual Windows app: Space play, Num . pause holds position, Num . resumes, Return stops and returns to beat 0, ruler click seeks to beat 10.\r\n");return 0;}catch(Exception e){File.WriteAllText(args[0],"FAIL "+e);return 1;}finally{if(engine!=null)engine.Dispose();if(form!=null){System.Windows.Forms.Timer timer=(System.Windows.Forms.Timer)form.GetType().GetField("_transportTimer",flags).GetValue(form);timer.Stop();form.Dispose();}}}
}